create extension if not exists "pgcrypto";
create table if not exists livestock(id uuid primary key default gen_random_uuid(),animal_code text not null unique,animal_type text not null,gender text,quantity numeric(12,2) not null default 1,purchase_price numeric(14,2) not null default 0,current_value numeric(14,2) not null default 0,status text not null default 'live',purchase_date date,notes text,created_at timestamptz not null default now());
create table if not exists livestock_transactions(id uuid primary key default gen_random_uuid(),livestock_id uuid references livestock(id) on delete set null,transaction_type text not null check(transaction_type in('PURCHASE','SALE','BIRTH','DEATH','TRANSFER','VALUATION','EXPENSE')),quantity numeric(12,2) not null default 0,amount numeric(14,2) not null default 0,cost_amount numeric(14,2) not null default 0,category text,transaction_date date not null default current_date,reference text,notes text,created_at timestamptz not null default now());
create table if not exists capital_transactions(id uuid primary key default gen_random_uuid(),transaction_type text not null check(transaction_type in('OPENING_CAPITAL','CAPITAL_IN','CAPITAL_OUT','LOAN_IN','LOAN_OUT')),amount numeric(14,2) not null default 0,transaction_date date not null default current_date,notes text,created_at timestamptz not null default now());
create table if not exists livestock_valuations(id uuid primary key default gen_random_uuid(),livestock_id uuid references livestock(id) on delete cascade,old_value numeric(14,2) not null default 0,new_value numeric(14,2) not null default 0,valuation_date date not null default current_date,notes text,created_at timestamptz not null default now());
create index if not exists idx_livestock_status on livestock(status);create index if not exists idx_livestock_transactions_date on livestock_transactions(transaction_date);create index if not exists idx_livestock_transactions_type on livestock_transactions(transaction_type);
